function readLines(path) {
  return fs.readFileSync(path, 'ascii').trimEnd().split('\n');
}

function readImage(path) {
  const lines = readLines(path);
  const [width, height] = lines[1].split(' ').map(Number);
  const pixels = lines.slice(3).flatMap(line => line.split(' ').map(Number));
  return { width, height, pixels };
}

function readTrig(path) {
  const cos = [], sin = [];
  for (const line of readLines(path)) {
    const [theta, c, s] = line.split(' ').map(Number);
    cos[theta] = c;
    sin[theta] = s;
  }
  return { cos, sin };
}

function readParams(path) {
  const params = {};
  for (const line of readLines(path)) {
    const [name, ...tokens] = line.split(' ');
    const values = tokens.map(Number);
    params[name] = name === 'gauss_kernel' ? values : values[0];
  }
  return params;
}

function writeImage(path, width, height, pixels) {
  const lines = ['P2', `${width} ${height}`, '255'];
  for (let y = 0; y < height; y++) {
    lines.push(Array.from(pixels.slice(y * width, (y + 1) * width)).join(' '));
  }
  fs.writeFileSync(path, lines.join('\n') + '\n', 'ascii');
}
function at(values, x, y, width, height) {
  x = Math.min(Math.max(x, 0), width - 1);
  y = Math.min(Math.max(y, 0), height - 1);
  return values[y * width + x];
}

function smooth(image, params) {
  const { width, height, pixels } = image;
  const size = params.gauss_size, half = (size - 1) / 2;
  const result = new Int32Array(width * height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let sum = 0;
      for (let j = 0; j < size; j++) {
        for (let i = 0; i < size; i++) {
          sum += params.gauss_kernel[j * size + i] *
            at(pixels, x + i - half, y + j - half, width, height);
        }
      }
      result[y * width + x] = Math.floor(sum / params.gauss_divisor);
    }
  }
  return result;
}

function gradient(values, width, height) {
  const gx = new Int32Array(width * height), gy = new Int32Array(width * height);
  const magnitude = new Int32Array(width * height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const q = [];
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) q.push(at(values, x + dx, y + dy, width, height));
      }
      const index = y * width + x;
      gx[index] = q[2] + 2 * q[5] + q[8] - q[0] - 2 * q[3] - q[6];
      gy[index] = q[6] + 2 * q[7] + q[8] - q[0] - 2 * q[1] - q[2];
      magnitude[index] = Math.abs(gx[index]) + Math.abs(gy[index]);
    }
  }
  return { gx, gy, magnitude };
}
function neighbors(index, width, height) {
  const x = index % width, y = Math.floor(index / width), result = [];
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const nx = x + dx, ny = y + dy;
      if (nx >= 0 && nx < width && ny >= 0 && ny < height) result.push(ny * width + nx);
    }
  }
  return result;
}

function directions(gx, gy) {
  return Uint8Array.from(gx, (value, index) => {
    const ax = Math.abs(value), ay = Math.abs(gy[index]);
    if (29 * ay <= 12 * ax) return 0;
    if (29 * ay >= 70 * ax) return 90;
    return value * gy[index] < 0 ? 45 : 135;
  });
}

function suppress(magnitude, direction, width, height) {
  const result = new Int32Array(width * height);
  const offset = { 0: -1, 45: 1 - width, 90: -width, 135: -1 - width };
  for (let y = 1; y < height - 1; y++) {
    for (let x = 1; x < width - 1; x++) {
      const index = y * width + x, delta = offset[direction[index]], m = magnitude[index];
      if (m > magnitude[index + delta] && m >= magnitude[index - delta]) result[index] = m;
    }
  }
  return result;
}

function hysteresis(nms, width, height, low, high) {
  const edges = new Uint8Array(nms.length), strong = new Uint8Array(nms.length);
  const weak = new Uint8Array(nms.length), queue = [];
  for (let i = 0; i < nms.length; i++) {
    if (nms[i] >= high) { strong[i] = 1; edges[i] = 1; queue.push(i); }
    else if (nms[i] >= low) weak[i] = 1;
  }
  for (let head = 0; head < queue.length; head++) {
    for (const next of neighbors(queue[head], width, height)) {
      if (!edges[next] && nms[next] >= low) { edges[next] = 1; queue.push(next); }
    }
  }
  return { edges, strong, weak };
}

function components(edges, width, height) {
  const visited = new Uint8Array(edges.length), groups = [];
  for (let i = 0; i < edges.length; i++) {
    if (!edges[i] || visited[i]) continue;
    const group = [i];
    visited[i] = 1;
    for (let head = 0; head < group.length; head++) {
      for (const next of neighbors(group[head], width, height)) {
        if (edges[next] && !visited[next]) { visited[next] = 1; group.push(next); }
      }
    }
    groups.push(group);
  }
  return groups;
}
const { neighbors } = require('./canny');
function detect(gx, gy, width, height, window, threshold, maximum) {
  const candidates = [];
  for (let index = 0; index < response.length; index++) {
    const value = response[index];
    if (value < threshold) continue;
    if (neighbors(index, width, height).some(next => response[next] > value ||
        (response[next] === value && next < index))) continue;
    candidates.push({ x: index % width, y: Math.floor(index / width), response: value });
  }
  return groups.map((pixels, i) => {
